sysevent_script_action.script:
try {
    var outboundSysID = event.parm1.toString();
    var messagetype = event.parm2.toString();
    new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().sendItmInstructions(outboundSysID, messagetype);
} catch (e) {
    gs.info('Script Action - MSS Unstructured Instructions: Unknown exception while processing Unstructured Instructions to ITM' + e.message);
}
